def compute_order_amount(on_hand_inventory, pipeline_orders):
    base_stock = 623.9874232861079  # OPT_PARAM: {"initial": 623.9874232861079, "min": 600, "max": 700, "type": "float"}
    pipeline_weight = 0.7543174717012517  # OPT_PARAM: {"initial": 0.7543174717012517, "min": 0.7, "max": 0.9, "type": "float"}
    responsiveness = 0.2  # OPT_PARAM: {"initial": 0.2, "min": 0.2, "max": 0.4, "type": "float"}
    demand_adjustment = 0.9  # OPT_PARAM: {"initial": 0.9, "min": 0.9, "max": 1.0, "type": "float"}

    smoothed_pipeline = sum(p * (responsiveness ** (i+1)) for i, p in enumerate(reversed(pipeline_orders)))
    net_position = on_hand_inventory + pipeline_weight * smoothed_pipeline
    order_amount = max(0, (base_stock - net_position) * demand_adjustment) * responsiveness
    return order_amount
